package com.logistics.notification;
import org.springframework.stereotype.Component;import jakarta.persistence.*;import java.time.*;import java.util.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.web.bind.annotation.*;import org.springframework.amqp.rabbit.annotation.RabbitListener;
@Entity class Notification { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; String recipient; String message; boolean read; Instant createdAt=Instant.now(); public UUID getId(){return id;} public String getRecipient(){return recipient;} public String getMessage(){return message;} public boolean isRead(){return read;} public Instant getCreatedAt(){return createdAt;} }
interface NotificationRepository extends JpaRepository<Notification,UUID>{}
@RestController @RequestMapping("/api/notifications") class NotificationController {private final NotificationRepository repo;NotificationController(NotificationRepository r){repo=r;} @GetMapping List<Notification> all(){return repo.findAll();} @PatchMapping("/{id}/read") Notification read(@PathVariable UUID id){var n=repo.findById(id).orElseThrow();n.read=true;return repo.save(n);}}
@Component class ShipmentEventConsumer {private final NotificationRepository repo;private final org.springframework.amqp.rabbit.core.RabbitTemplate rabbit;ShipmentEventConsumer(NotificationRepository r,org.springframework.amqp.rabbit.core.RabbitTemplate t){repo=r;rabbit=t;} @RabbitListener(queues="notification.shipment-events") void onShipment(Map<String,Object> event){var n=new Notification();n.recipient=String.valueOf(event.getOrDefault("orderId","system"));n.message=("ShipmentDelivered".equals(event.get("eventType"))?"Shipment delivered: ":"Shipment created: ")+event.get("shipmentId");repo.save(n);rabbit.convertAndSend("logistics.events","NotificationCreated",Map.of("eventType","NotificationCreated","notificationId",n.id.toString()));}}

